    ///
    /// * No concurrent access to the slot.
    fn has_value(&self, rx_fields: &RxFields<T>) -> bool {
        let list = &rx_fields.list;
        let tx = &*self.inner.tx;

        let tail_position = tx.tail_position.load(Acquire);
        let tail_block_ptr = tx.block_tail.load(Acquire);

        let current_head = list.head;
        let mut cursor = list.free_head;

        if cursor.as_ptr() == tail_block_ptr && cursor != current_head {
            cursor = current_head;
        }

        while cursor != current_head {
            let cursor_block = unsafe { cursor.as_ref() };
            match cursor_block.load_next(Acquire) {
                Some(next) => cursor = next,
                None => {
                    cursor = current_head;
                    break;
                }
            }
        }

